/// Draws a Lucide icon by name, like `<Name className="w-4 h-4" />` in the React app.
class LIcon extends StatelessWidget {
  const LIcon(this.name, {super.key, this.size = 16, this.color = const Color(0xFF0F172A), this.strokeWidth = 2});
  final String name;
  final double size;
  final Color color;
  final double strokeWidth;

  @override
  Widget build(BuildContext context) {
    final body = _paths[name] ?? '';
    final svg = '<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" '
        'stroke="#000000" stroke-width="$strokeWidth" stroke-linecap="round" stroke-linejoin="round">$body</svg>';
    return SvgPicture.string(svg, width: size, height: size, colorFilter: ColorFilter.mode(color, BlendMode.srcIn));
  }
}
